function getDatadogTranslation(key, lang) {
    if (datadogTranslations[lang] && datadogTranslations[lang][key]) {
        return datadogTranslations[lang][key];
    }
    if (datadogTranslations.en && datadogTranslations.en[key]) {
        return datadogTranslations.en[key];
    }
    return null;
}

function applyDatadogTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.datadog.')) {
            const translation = getDatadogTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyDatadogTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyDatadogTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyDatadogTranslations(currentLang);
}


